<script setup>
import {reactive,onMounted} from 'vue';import {useRecords} from '../stores/records.js';import {useFeedback} from '../stores/feedback.js';import Feedback from '../components/Feedback.vue';import RecordTable from '../components/RecordTable.vue';const store=useRecords();const {busy,error,success,run}=useFeedback();const form=reactive({id:'',name:''});const columns=[{key:'id',label:'Course ID'},{key:'name',label:'Course name'}];onMounted(()=>run(()=>store.loadCourses()));function add(){run(async()=>{await store.addCourse({...form});form.id='';form.name='';},'Course added successfully.');}function remove(record){if(window.confirm(`Delete ${record.name} and all related enrollments?`))run(()=>store.removeCourse(record.id),'Course deleted successfully.');}
</script>
<template><div class="heading"><p class="eyebrow">CATALOG</p><h1>Courses</h1><p>Create and maintain the course catalog.</p></div><Feedback :busy="busy" :error="error" :success="success"/><div class="layout"><section class="panel"><h2>Add course</h2><form @submit.prevent="add"><label for="cid">Course ID</label><input id="cid" v-model.trim="form.id" required maxlength="200" placeholder="CIS 3339"/><label for="cname">Course name</label><input id="cname" v-model.trim="form.name" required maxlength="200" placeholder="Enterprise Applications Development"/><button :disabled="busy">Add course</button></form></section><section class="panel"><h2>Course catalog</h2><RecordTable :rows="store.courses" :columns="columns" :busy="busy" deletable @remove="remove"/></section></div></template>
